CREATE UNIQUE INDEX IF NOT EXISTS nv_portal_staff_tenant ON public.funcionarios(empresa_id,id);
ALTER TABLE public.faturas ADD COLUMN IF NOT EXISTS billing_meta jsonb;
CREATE TABLE public.nv_portal_units(empresa_id uuid PRIMARY KEY REFERENCES public.empresas(id),slug text NOT NULL UNIQUE CHECK(slug ~ '^[a-z0-9][a-z0-9-]{2,49}$'),enabled boolean NOT NULL DEFAULT false,public_name text NOT NULL,phone text NOT NULL DEFAULT '',address text NOT NULL DEFAULT '',updated_by text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.nv_portal_accounts(id uuid PRIMARY KEY,username text NOT NULL UNIQUE,password_hash text NOT NULL,display_name text NOT NULL,active boolean NOT NULL DEFAULT true,failures integer NOT NULL DEFAULT 0,locked_until timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.nv_portal_sessions(token_hash text PRIMARY KEY,account_id uuid NOT NULL REFERENCES public.nv_portal_accounts(id),csrf text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),last_seen timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE public.nv_portal_links(account_id uuid NOT NULL REFERENCES public.nv_portal_accounts(id),empresa_id uuid NOT NULL REFERENCES public.empresas(id),patient_id integer NOT NULL,verified_by text NOT NULL,verification_note text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(account_id,empresa_id),UNIQUE(empresa_id,patient_id),FOREIGN KEY(empresa_id,patient_id) REFERENCES public.pacientes(empresa_id,id));
CREATE TABLE public.nv_portal_requests(id uuid PRIMARY KEY,account_id uuid NOT NULL REFERENCES public.nv_portal_accounts(id),empresa_id uuid NOT NULL REFERENCES public.empresas(id),kind text NOT NULL CHECK(kind IN ('cadastro','contacto','seguro')),data jsonb NOT NULL,status text NOT NULL DEFAULT 'pendente' CHECK(status IN ('pendente','aprovado','recusado')),response text NOT NULL DEFAULT '',reviewed_by text,created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz);
CREATE UNIQUE INDEX nv_portal_pending_registration ON public.nv_portal_requests(account_id,empresa_id) WHERE kind='cadastro' AND status='pendente';
CREATE TABLE public.nv_portal_resets(id uuid PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),username text NOT NULL,contact text NOT NULL,status text NOT NULL DEFAULT 'pendente',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.nv_portal_tokens(token_hash text PRIMARY KEY,account_id uuid NOT NULL REFERENCES public.nv_portal_accounts(id),created_by text NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE public.nv_portal_slots(id uuid PRIMARY KEY,empresa_id uuid NOT NULL REFERENCES public.empresas(id),clinician_id uuid NOT NULL,specialty text NOT NULL,location text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true,created_by text NOT NULL,UNIQUE(empresa_id,id),CHECK(ends_at>starts_at),FOREIGN KEY(empresa_id,clinician_id) REFERENCES public.funcionarios(empresa_id,id));
CREATE TABLE public.nv_portal_appointments(id uuid PRIMARY KEY,empresa_id uuid NOT NULL,slot_id uuid NOT NULL,account_id uuid NOT NULL REFERENCES public.nv_portal_accounts(id),patient_id integer NOT NULL,status text NOT NULL DEFAULT 'marcada' CHECK(status IN ('marcada','cancelada','realizada','faltou')),request_id uuid NOT NULL,status_note text NOT NULL DEFAULT '',updated_by text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,request_id),FOREIGN KEY(empresa_id,slot_id) REFERENCES public.nv_portal_slots(empresa_id,id),FOREIGN KEY(empresa_id,patient_id) REFERENCES public.pacientes(empresa_id,id));
CREATE UNIQUE INDEX nv_portal_slot_occupied ON public.nv_portal_appointments(slot_id) WHERE status IN ('marcada','realizada','faltou');
CREATE TABLE public.nv_portal_documents(id uuid PRIMARY KEY,empresa_id uuid NOT NULL,patient_id integer NOT NULL,kind text NOT NULL CHECK(kind IN ('resumo','receita')),title text NOT NULL,body text NOT NULL,author_id uuid NOT NULL,author_name text NOT NULL,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz,revoke_reason text,FOREIGN KEY(empresa_id,patient_id) REFERENCES public.pacientes(empresa_id,id),FOREIGN KEY(empresa_id,author_id) REFERENCES public.funcionarios(empresa_id,id));
CREATE TABLE public.nv_portal_audit(id bigserial PRIMARY KEY,empresa_id uuid REFERENCES public.empresas(id),actor text NOT NULL,action text NOT NULL,reference text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX nv_portal_audit_org ON public.nv_portal_audit(empresa_id,id DESC);
CREATE INDEX nv_portal_slots_time ON public.nv_portal_slots(empresa_id,starts_at);
CREATE INDEX nv_portal_requests_org ON public.nv_portal_requests(empresa_id,status,created_at);
